package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Figures;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Takes the person's statement: their due-total now, the sum of their counting claims' figures
 *  with any late charges, each at least the floor (n/a when there is no rate today and none has a figure), at most the sheet's cap, dated the sheet's today. Every claim
 *  of theirs that counts (not an OPEN one dated within one of their holds) is bound to its rate figure now, without its late charge or the floor; every other one is unbound. */
public class TakeStatement {
    public void take(@Val StatementRequest request, @Val Person person, Claims claims, Figures figures,
            Rates rates, Sheets sheets, Settings settings, People people, Out<Statement> statement) {
        Person locked = people.lock(person.getSheetId(), person.getId());
        person.setStatementCount(locked.getStatementCount());
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean any = false;
        int counted = 0;
        for (Claim claim : claims.ofPerson(person.getSheetId(), person.getId())) {
            if (person.counts(claim)) {
                BigDecimal bound = figures.figure(claim, person.gradeOn(claim.getDate()));
                // The statement binds the rate figure; the late charge and floor on top keep following today.
                BigDecimal figure = figures.due(claim, person.gradeOn(claim.getDate()));
                claim.setStated(true);
                claim.setStatedDue(bound);
                counted++;
                if (figure != null) {
                    total = total.add(figure);
                    any = true;
                }
            } else {
                claim.setStated(false);
                claim.setStatedDue(null);
            }
            claims.save(claim);
        }
        var today = sheets.today(person.getSheetId());
        BigDecimal dueTotal = !any && rates.pct(person.getSheetId(), person.gradeOn(today), today) == null ? null
                : settings.capped(person.getSheetId(), total);
        person.setStatementCount(person.getStatementCount() + 1);
        person.setStatedTotal(dueTotal);
        person.setStatementDate(today);
        people.saveStatement(person);
        statement.set(new Statement(dueTotal, counted, request.user()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Runs after the statement is saved. */
public class RecordStatement {
    public void record(@Val Statement statement, @Val Person person, Audit audit) {
        audit.record("STATEMENT sheet=" + person.getSheetId() + " by=" + statement.user()
                + " name=" + person.getName()
                + " due-total=" + (statement.dueTotal() != null ? statement.dueTotal().toPlainString() : "n/a")
                + " claims=" + statement.claims());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateStatement {
    public void validate(@RequestBody StatementRequest request, Out<StatementRequest> body, Out<Actor> actor) {
        actor.set(new Actor(request != null ? request.user() : null));
        body.set(request != null ? request : new StatementRequest(null));
    }
}
