import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { useClaims } from '../claims/useClaims';
import { type Person } from '../people/usePeople';
import { showDue, useRates } from '../rates/useRates';
import { useFloor, useLate } from '../settings/useSettings';
import { personPeriodDueCents, usePeriods } from './usePeriods';

/** One header per period on the sheet. */
function PeriodColumns({ sheet }: { user: string; sheet: string }) {
  const { data: periods = [] } = usePeriods(sheet);
  return (
    <>
      {periods.map((p) => (
        <th key={p.name}>{p.name}</th>
      ))}
    </>
  );
}

/**
 * A person's due-total for every period on the sheet: the due of their claims dated in it that were
 * counted at the end of its last day (by their status log),
 * or, once the period is closed, the figure fixed then (0.00 for a person added since).
 */
function PersonPeriods({ sheet, person }: { user: string; sheet: string; person: Person }) {
  const { data: periods = [] } = usePeriods(sheet);
  const { data: claims = [] } = useClaims(sheet);
  const { data: rates = [] } = useRates(sheet);
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  return (
    <>
      {periods.map((p) => (
        <td key={p.name} data-testid={`person-period-${p.name}-due-total`}>
          {showDue(personPeriodDueCents(p, person, claims, rates, floor, late))}
        </td>
      ))}
    </>
  );
}

export const contributions = [
  PersonColumns.fill({ order: 15, Component: PeriodColumns }),
  PersonCells.fill({ order: 15, Component: PersonPeriods }),
];
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimLog;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Figures;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import org.springframework.stereotype.Service;

/** Closes a period, fixing its due-total as the screen shows it now: the figures (as shown now) of
 *  everyone's claims dated in it that were counted (OPEN, PENDING or SETTLED) by the status each had
 *  at the end of the period's last day, as its status log records it — not deferred ones, nor
 *  ones open then and dated within their person's hold, unless stated — n/a ones skipped. Each
 *  person's due-total for it is fixed too, and the period's is their sum. Used by a close by hand
 *  and by the auto close of a today change. */
@Service
public class PeriodCloser {

    private final Periods periods;
    private final Claims claims;
    private final People people;
    private final Figures figures;
    private final ClaimLog log;

    public PeriodCloser(Periods periods, Claims claims, People people, Figures figures, ClaimLog log) {
        this.periods = periods;
        this.claims = claims;
        this.people = people;
        this.figures = figures;
        this.log = log;
    }

    /** Close the open or soft-closed period; the period as it is once closed. */
    public Period close(Period period) {
        return close(period, false);
    }

    /** Close the period, or soft-close it when `soft`; the period as it is then. */
    public Period close(Period period, boolean soft) {
        Map<Long, Person> personOf = people.onSheet(period.sheetId()).stream()
                .collect(Collectors.toMap(Person::getId, p -> p));
        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
        for (Long id : personOf.keySet()) personTotals.put(id, BigDecimal.ZERO.setScale(2));
        Map<Long, ClaimStatus> atEnd = log.statusesAt(period.sheetId(), period.to());
        for (Claim claim : claims.onSheet(period.sheetId())) {
            if (!period.contains(claim.getDate())) continue;
            Person person = personOf.get(claim.getPersonId());
            if (person == null || !person.counts(claim,
                    atEnd.containsKey(claim.getId()) ? atEnd.get(claim.getId()) : claim.getStatus())) continue;
            BigDecimal figure = figures.due(claim, person.gradeOn(claim.getDate()));
            if (figure != null) personTotals.merge(person.getId(), figure, BigDecimal::add);
        }
        BigDecimal total = personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        periods.close(period, total, personTotals, soft);
        return new Period(period.sheetId(), period.name(), period.from(), period.to(), true, total, soft);
    }
}
    public void add(Period period) {
        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date) VALUES (?, ?, ?, ?)",
                period.sheetId(), period.name(), Date.valueOf(period.from()), Date.valueOf(period.to()));
    }

    /** Close (or, when `soft`, soft-close) the period, fixing its due-total and each person's (by
     *  person id) afresh. */
    public void close(Period period, BigDecimal total, Map<Long, BigDecimal> personTotals, boolean soft) {
        jdbc.update("UPDATE period SET closed = TRUE, soft = ?, closed_total = ? WHERE sheet_id = ? AND name = ?",
                soft, total, period.sheetId(), period.name());
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_name = ?",
                period.sheetId(), period.name());
        personTotals.forEach((personId, personTotal) -> jdbc.update(
                "INSERT INTO period_person_total (sheet_id, period_name, person_id, total) VALUES (?, ?, ?, ?)",
                period.sheetId(), period.name(), personId, personTotal));
    }

    /** Each person's due-total fixed when the period was closed, by person id; empty while it is open. */
    public Map<Long, BigDecimal> personTotals(Period period) {
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        jdbc.query("SELECT person_id, total FROM period_person_total WHERE sheet_id = ? AND period_name = ?"
                + " ORDER BY person_id", rs -> {
                    totals.put(rs.getLong("person_id"), rs.getBigDecimal("total"));
                }, period.sheetId(), period.name());
        return totals;
    }

    /** Reopen the period: its due-total, and each person's, is live again. */
    public void reopen(Period period) {
        jdbc.update("UPDATE period SET closed = FALSE, soft = FALSE, closed_total = NULL WHERE sheet_id = ? AND name = ?",
                period.sheetId(), period.name());
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_name = ?",
                period.sheetId(), period.name());
    }

    private static Period period(ResultSet rs, int i) throws SQLException {
        return new Period(rs.getString("sheet_id"), rs.getString("name"), rs.getDate("from_date").toLocalDate(),
                rs.getDate("to_date").toLocalDate(), rs.getBoolean("closed"), rs.getBigDecimal("closed_total"),
                rs.getBoolean("soft"));
    }
}

